package com.mirigangneung.course.domain; import com.mirigangneung.place.domain.Place; import jakarta.persistence.*; import java.util.*;
@Entity @Table(name="course_stops") public class CourseStop { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY) private Course course; @ManyToOne(fetch=FetchType.LAZY) private Place place; private int sequence; private String arrivalTime; private int stayMinutes; private String crowdLevel; private String note; private boolean isOnePick; private Double latitudeSnapshot,longitudeSnapshot; protected CourseStop(){} public CourseStop(Course c,Place p,int seq,boolean one){course=c;place=p;sequence=seq;isOnePick=one;stayMinutes=60;arrivalTime="09:00";crowdLevel="LOW";note=one?"원픽 장소":"선택한 여행 유형과 가까운 추천 장소";latitudeSnapshot=p.getLatitude();longitudeSnapshot=p.getLongitude();} public int getSequence(){return sequence;}public Place getPlace(){return place;}public String getArrivalTime(){return arrivalTime;}public int getStayMinutes(){return stayMinutes;}public String getCrowdLevel(){return crowdLevel;}public String getNote(){return note;}public boolean isOnePick(){return isOnePick;}public Double getLatitudeSnapshot(){return latitudeSnapshot;}public Double getLongitudeSnapshot(){return longitudeSnapshot;}}
